import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>

#define K 3
#define C_IN 3
#define C_OUT 32
#define TILE 16
#define REG_W 2
#define OUT_TILE_W (TILE*REG_W)
__global__ void __launch_bounds__(TILE*TILE, 4) conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int N, int H, int W, int H_out, int W_out)
{
    __shared__ __nv_bfloat16 s_weight[C_OUT][C_IN*K*K];
    __shared__ __nv_bfloat16 s_input[C_IN][TILE+K-1][OUT_TILE_W+K-1];
    int tx = threadIdx.x; // 0..TILE-1
    int ty = threadIdx.y; // 0..TILE-1
    int tid = ty * TILE + tx;
    int n = blockIdx.z;
    int tile_h_start = blockIdx.y * TILE;
    int tile_w_start = blockIdx.x * OUT_TILE_W;
    const int wsize = C_IN*K*K;
    const int wtotal = C_OUT*wsize;
    for (int i = tid; i < wtotal; i += TILE*TILE) {
        int c_out_i = i / wsize;
        int off = i % wsize;
        s_weight[c_out_i][off] = weight[c_out_i*wsize + off];
    }
    const int smem_h = TILE + K - 1;
    const int smem_w = OUT_TILE_W + K - 1;
    const int smem_w_pairs = smem_w / 2;
    const int smem_size_pairs = smem_h * smem_w_pairs;
    #pragma unroll
    for (int c_in = 0; c_in < C_IN; c_in++) {
        for (int i = tid; i < smem_size_pairs; i += TILE*TILE) {
            int sh = i / smem_w_pairs;
            int sw_pair = i % smem_w_pairs;
            int sw = sw_pair * 2;
            int h_in = tile_h_start + sh;
            int w_in = tile_w_start + sw;
            __nv_bfloat16 v0 = __float2bfloat16(0.0f);
            __nv_bfloat16 v1 = __float2bfloat16(0.0f);
            if (h_in < H) {
                long base_idx = ((long)n*C_IN + c_in)*H*W + (long)h_in*W + w_in;
                if (w_in + 1 < W) {
                    __nv_bfloat162 val2 = *reinterpret_cast<const __nv_bfloat162*>(&input[base_idx]);
                    v0 = val2.x;
                    v1 = val2.y;
                } else if (w_in < W) {
                    v0 = input[base_idx];
                }
            }
            s_input[c_in][sh][sw] = v0;
            s_input[c_in][sh][sw + 1] = v1;
        }
    }
    __syncthreads();
    int h_out = tile_h_start + ty;
    int w_out0 = tile_w_start + tx;
    int w_out1 = w_out0 + TILE;
    bool valid_h = (h_out < H_out);
    bool valid0 = valid_h && (w_out0 < W_out);
    bool valid1 = valid_h && (w_out1 < W_out);
    if (valid0 || valid1) {
        __nv_bfloat162 in_cache[C_IN][K][K];
        #pragma unroll
        for (int c_in = 0; c_in < C_IN; c_in++) {
            #pragma unroll
            for (int kh = 0; kh < K; kh++) {
                #pragma unroll
                for (int kw = 0; kw < K; kw++) {
                    __nv_bfloat16 v0 = s_input[c_in][ty+kh][tx+kw];
                    __nv_bfloat16 v1 = s_input[c_in][ty+kh][tx+TILE+kw];
                    in_cache[c_in][kh][kw] = __halves2bfloat162(v0, v1);
                }
            }
        }
        #pragma unroll 2
        for (int c_out = 0; c_out < C_OUT; c_out++) {
            float acc0 = 0.0f;
            float acc1 = 0.0f;
            #pragma unroll
            for (int c_in = 0; c_in < C_IN; c_in++) {
                #pragma unroll
                for (int kh = 0; kh < K; kh++) {
                    #pragma unroll
                    for (int kw = 0; kw < K; kw++) {
                        float w_val = __bfloat162float(s_weight[c_out][c_in*K*K + kh*K + kw]);
                        __nv_bfloat162 in2 = in_cache[c_in][kh][kw];
                        acc0 += __low2float(in2) * w_val;
                        acc1 += __high2float(in2) * w_val;
                    }
                }
            }
            if (valid0) {
                long out_idx0 = ((long)n*C_OUT + c_out)*H_out*W_out + (long)h_out*W_out + w_out0;
                output[out_idx0] = __float2bfloat16(acc0);
            }
            if (valid1) {
                long out_idx1 = ((long)n*C_OUT + c_out)*H_out*W_out + (long)h_out*W_out + w_out1;
                output[out_idx1] = __float2bfloat16(acc1);
            }
        }
    }
}
torch::Tensor conv2d_bf16_forward(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kBFloat16, "input must be bf16");
    TORCH_CHECK(weight.dtype() == torch::kBFloat16, "weight must be bf16");
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int Kh = weight.size(2);
    int Kw = weight.size(3);
    int H_out = H - Kh + 1;
    int W_out = W - Kw + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    dim3 threads(TILE, TILE);
    dim3 blocks((W_out + OUT_TILE_W - 1) / OUT_TILE_W,
                (H_out + TILE - 1) / TILE,
                N);
    conv2d_bf16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __nv_bfloat16*>(input.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        N, H, W, H_out, W_out
    );
    return output;
}
